INSERT INTO tools (slug, name, url, domain, category, badge, users, best_for, description, pros, cons) VALUES
('meta-ai', 'Meta AI', 'https://meta.ai', 'meta.ai', 'chat', 'free', '500M+', 'Social media, everyday tasks, free chat', 'Free AI assistant by Meta built into WhatsApp, Instagram and Messenger. Powered by Llama 4.', ARRAY['Completely free with no usage limits or subscriptions', 'Built into WhatsApp, Instagram and Messenger — no extra app needed', 'Powered by Llama 4, competitive with GPT-4 quality'], ARRAY['Privacy concern — Meta uses conversations to improve ad targeting', 'Less capable than Claude or GPT-4o on complex reasoning tasks']),
('chatgpt', 'ChatGPT', 'https://chat.openai.com', 'chat.openai.com', 'chat', 'freemium', '200M+', 'General tasks, writing, coding', 'The most popular AI chat by OpenAI. GPT-4o for text, images and voice. Used by 200M+ people.', ARRAY['Largest AI model ecosystem — GPT-4o, o3, vision, voice all in one place', 'GPT Store with 1M+ custom GPTs for every use case', 'Industry standard — most integrations and third-party tools built for it'], ARRAY['Free tier limits hit quickly; Plus costs $20/month', 'Can hallucinate confidently without citing sources']),
('microsoft-copilot', 'Microsoft Copilot', 'https://copilot.microsoft.com', 'copilot.microsoft.com', 'chat', 'freemium', '300M+', 'Windows, Office 365, everyday tasks', 'AI assistant built into Windows 11, Edge and Microsoft 365. GPT-4 powered with Bing search.', ARRAY['Free for all Windows 11 users — no signup required', 'Deep Office 365 integration: works inside Word, Excel, Outlook, Teams', 'Bing search built-in for real-time, up-to-date answers'], ARRAY['Quality inconsistent compared to native ChatGPT or Claude', 'Full Microsoft 365 Copilot costs an extra $30/user/month']),
('gemini', 'Gemini', 'https://gemini.google.com', 'gemini.google.com', 'chat', 'freemium', '100M+', 'Current information, Google ecosystem', 'Google''s AI with real-time internet access. Gemini 2.0 Ultra with multimodal capabilities.', ARRAY['Best Google ecosystem integration — Gmail, Docs, Drive, YouTube', 'Gemini 2.0 Ultra leads multimodal benchmarks in 2026', '1M token context window in Gemini 1.5 Pro — handles entire codebases'], ARRAY['Google collects data for product improvement by default', 'Still behind Claude and GPT-4o on complex instruction-following']),
('deepseek', 'DeepSeek', 'https://chat.deepseek.com', 'chat.deepseek.com', 'chat', 'free', '30M+', 'Free GPT-4 alternative', 'Chinese LLM rivaling GPT-4 quality — completely free. Open API and web interface available.', ARRAY['GPT-4 quality completely free — no rate limits on web interface', 'Fully open-source weights available for local and commercial deployment', 'Exceptional math, coding and reasoning benchmarks'], ARRAY['Chinese company — data privacy concerns for sensitive business content', 'Servers can be slow or temporarily unavailable during peak hours']),
('claude', 'Claude', 'https://claude.ai', 'claude.ai', 'chat', 'freemium', '20M+', 'Long texts, document analysis, code', 'AI assistant by Anthropic. Best for long documents, analysis and code. 200K token context window.', ARRAY['Best at following complex multi-step instructions without losing context', '200K token context — analyze entire books, PDFs or codebases in one go', 'Fewest hallucinations of any frontier model — most accurate and careful'], ARRAY['No image generation or real-time browsing on free tier', 'API pricing slightly higher than GPT-4o equivalents per token']),
('perplexity', 'Perplexity', 'https://perplexity.ai', 'perplexity.ai', 'chat', 'freemium', '15M+', 'Research, sourced answers', 'AI search with cited sources. Deep Research mode for detailed multi-page analysis on any topic.', ARRAY['Every answer cites sources — easy to verify, no blind hallucinations', 'Deep Research mode produces research-quality multi-page reports', 'Real-time web search unlike most AI chatbots on free plan'], ARRAY['Weaker at creative writing and nuanced reasoning vs Claude or GPT-4', 'Unlimited Deep Research requires Pro subscription ($20/month)']),
('grok', 'Grok', 'https://x.com/i/grok', 'x.com', 'chat', 'freemium', '10M+', 'Real-time news, X/Twitter insights', 'AI by xAI with real-time access to X/Twitter data. Great for trending topics, news and unfiltered answers.', ARRAY['Real-time X/Twitter data — unmatched for trending topics and social sentiment', 'Fewer content restrictions than OpenAI or Anthropic models', 'Free for all X users; SuperGrok unlocks extended capabilities'], ARRAY['X Premium subscription needed for full Grok access ($8/month)', 'Smaller knowledge base and shorter context than Claude or GPT-4o']),
('microsoft-copilot-studio', 'Microsoft Copilot Studio', 'https://copilotstudio.microsoft.com', 'copilotstudio.microsoft.com', 'agents', 'freemium', '1M+', 'Enterprise agents, Microsoft ecosystem', 'Build and deploy custom AI agents for your business. Direct integration with Office 365 and Teams.', ARRAY['Native Teams, SharePoint and Office 365 integration out of the box', 'No-code agent builder with enterprise-grade security and compliance (SOC2, GDPR)', 'Pre-built connectors to 1,000+ business systems'], ARRAY['Per-message pricing can become expensive at scale', 'Best value only for organizations already on Microsoft 365']),
('n8n', 'n8n', 'https://n8n.io', 'n8n.io', 'agents', 'freemium', '500K+', 'Workflow automation, AI pipelines', 'Open-source workflow automation. Chain AI models, APIs and 400+ apps with a visual editor.', ARRAY['Open-source — self-host for unlimited workflows at zero cost', '400+ integrations including all major AI APIs (OpenAI, Anthropic, Gemini)', 'Most flexible routing and data transformation logic of any automation tool'], ARRAY['Steeper learning curve than Make or Zapier — JSON expressions required for advanced flows', 'Cloud-hosted version gets expensive at scale']),
('make', 'Make', 'https://make.com', 'make.com', 'agents', 'freemium', '500K+', 'Complex automations, app integrations', 'Visual automation platform connecting 1,000+ apps. More flexible than Zapier with advanced data routing.', ARRAY['Visual canvas makes even complex multi-step workflows easy to read and debug', '1,000+ app connectors — more than Zapier at lower price', 'Handles data transformation, iteration and error handling visually'], ARRAY['Operations-based pricing can be unpredictable for high-volume workflows', 'No native AI model hosting — always delegates to external API calls']),
('autogpt', 'AutoGPT', 'https://agpt.co', 'agpt.co', 'agents', 'free', '200K+', 'Autonomous tasks, open-source AI agents', 'Open-source autonomous AI agent. Give it a goal — it breaks it into steps and executes them automatically.', ARRAY['Fully open-source — inspect, fork and modify every component', 'Runs fully autonomously on long-horizon goals with minimal human input', 'Active community with plugins for web browsing, file management, coding'], ARRAY['Unreliable on complex tasks — agents can loop or hallucinate mid-execution', 'Requires technical setup and a funded OpenAI API key']),
('lindy', 'Lindy', 'https://lindy.ai', 'lindy.ai', 'agents', 'freemium', '100K+', 'Email agents, scheduling, support bots', 'Build AI agents for email, scheduling and customer support in minutes. No code needed.', ARRAY['Easiest agent builder — deploy a working email or scheduling agent in minutes', 'Pre-built templates for common business use cases', 'Native calendar, email and Slack integrations'], ARRAY['Less flexible than n8n or Make for custom multi-step logic', 'Pricing scales with number of runs — can get expensive for high-volume agents']),
('relevance-ai', 'Relevance AI', 'https://relevanceai.com', 'relevanceai.com', 'agents', 'freemium', '100K+', 'Multi-agent teams, sales and support bots', 'No-code platform to build, train and deploy AI agents and multi-agent teams for any business workflow.', ARRAY['Best multi-agent orchestration — create teams of specialized agents that collaborate', 'Fine-tune agents on your own data and documents with no code', 'Enterprise security with audit trail and role-based access'], ARRAY['More expensive than simpler tools for basic single-agent use cases', 'Fewer third-party integrations compared to Make or Zapier']),
('replit', 'Replit', 'https://replit.com', 'replit.com', 'code', 'freemium', '10M+', 'Cloud coding, learning, quick deploys', 'Cloud coding environment with AI agent that writes, runs and deploys code directly in the browser.', ARRAY['Zero setup — open browser, start coding in any language instantly', 'AI agent writes, runs and debugs code in the same environment', 'Best platform for learning to code and for quick prototypes'], ARRAY['Performance limited vs local development for large projects', 'Not suitable for complex production codebases']),
