('grammarly', 'Grammarly', 'https://grammarly.com', 'grammarly.com', 'writing', 'freemium', '50M+', 'Grammar, style, text improvement', 'Grammar, style and tone checker. Browser extension that works everywhere you write.', ARRAY['Works everywhere — browser extension, Word, Google Docs, Slack', 'Tone detection tells you how your writing sounds to the reader', 'Free tier covers most common grammar and spelling corrections'], ARRAY['Advanced style and clarity suggestions locked behind Premium ($12/month)', 'Can over-correct intentional stylistic choices in creative writing']),
('quillbot', 'QuillBot', 'https://quillbot.com', 'quillbot.com', 'writing', 'freemium', '30M+', 'Paraphrasing, summarizing, rewriting', 'Free AI paraphrasing and summarizing tool. Rewrites text in 8 different styles, 125 words free per use.', ARRAY['7 paraphrasing modes: Standard, Fluency, Academic, Simple, Creative and more', 'Chrome extension rewrites any selected text in-place on any website', 'Summarizer handles long articles in seconds'], ARRAY['Free tier limited to 125 words per paraphrase', 'Can sometimes subtly change meaning while rewriting']),
('writesonic', 'Writesonic', 'https://writesonic.com', 'writesonic.com', 'writing', 'freemium', '5M+', 'SEO articles, social content', 'AI for SEO articles, ad copy and social posts with built-in optimization tools.', ARRAY['60+ templates cover every type of marketing content', 'Chatsonic browses the web for real-time accurate content', 'Brand Voice feature learns and replicates your writing style'], ARRAY['Output quality inconsistent — often needs heavy editing before publishing', 'Credits system confusing — different actions cost different amounts']),
('hemingway-editor', 'Hemingway Editor', 'https://hemingwayapp.com', 'hemingwayapp.com', 'writing', 'free', '2M+', 'Clear writing, readability, editing', 'Free readability tool that highlights complex sentences, passive voice and adverbs. No signup needed.', ARRAY['Completely free online version — no signup, no limits', 'Color-coded highlights make reading grade level visible at a glance', 'Simple distraction-free interface — just paste and see results instantly'], ARRAY['No AI writing assistance — analysis and highlighting only', 'Can flag intentional stylistic choices as errors']),
('jasper', 'Jasper', 'https://jasper.ai', 'jasper.ai', 'writing', 'paid', '100K+', 'Marketing content, SEO writing', 'Professional AI copywriter with templates for blogs, ads, email campaigns and SEO content.', ARRAY['Marketing-specific templates and brand tone control better than generic AI', 'Jasper Campaigns produces coordinated multi-channel content', 'Enterprise collaboration: shared brand voice across the whole team'], ARRAY['Very expensive — starts at $39/month', 'Core AI quality not meaningfully better than Claude or GPT-4 used directly']),
('semrush', 'Semrush', 'https://semrush.com', 'semrush.com', 'marketing', 'freemium', '10M+', 'SEO research, competitor analysis', 'All-in-one SEO platform with AI writing assistant, keyword research and competitor gap analysis.', ARRAY['Most comprehensive SEO data — 25B+ keywords, 43T backlinks indexed', 'See exactly what keywords competitors rank for and where you have gaps', 'Replaces 5-6 separate SEO tools: rank tracker, audit, backlinks, content, ads'], ARRAY['Very expensive — starts at $117/month for meaningful usage', 'Data overload for beginners without prior SEO knowledge']),
('copy-ai', 'Copy.ai', 'https://copy.ai', 'copy.ai', 'marketing', 'freemium', '10M+', 'Ad copy, email campaigns, social posts', 'AI marketing copy for ads, emails and social media. 90+ templates, workflow automations and free tier.', ARRAY['90+ templates cover every marketing use case from cold emails to product descriptions', 'Workflows automate entire content pipelines end-to-end', 'Generous free tier with 2,000 words/month'], ARRAY['Output quality variable — often needs heavy editing', 'Less compelling now that Claude or GPT-4 handle same tasks for less money']),
